package fr.lg30.waynesworld;
import javax.imageio.ImageIO; import java.awt.image.BufferedImage; import java.io.*; import java.nio.file.*; import java.util.*;
public final class AllTests {static int tests;static void ok(boolean v,String n){tests++;if(!v)throw new AssertionError(n);System.out.println("PASS "+n);}static byte[] res(String n)throws Exception{try(var in=AllTests.class.getResourceAsStream(n)){return in.readAllBytes();}}
 public static void main(String[] z)throws Exception{Path usa=Path.of("Wayne's World (USA).md"),fr;try(var s=Files.list(Path.of("."))){fr=s.filter(p->p.getFileName().toString().startsWith("Waynes_World_FR_complete_183_bulles")&&p.toString().endsWith(".bin")).findFirst().orElseThrow();}ok(Files.isRegularFile(usa)&&Files.isRegularFile(fr)&&Files.isRegularFile(Path.of("Image.png")),"présence références");byte[] u=Files.readAllBytes(usa),f=Files.readAllBytes(fr);ok(Hashes.of(u).equals(RomValidator.USA),"hashes USA");var fh=new Hashes(1085408,"6762266d","3f9b17922988941d9c652803cf787f2a","c24eeb619f7b263953a837b6c23a405e8b4af783");ok(Hashes.of(f).equals(fh),"hashes FR");byte[] rebuilt=new FrenchTranslationPatch().apply(u);ok(Arrays.equals(rebuilt,f),"delta byte-for-byte");ok(Hashes.of(rebuilt).equals(fh),"hashes reconstruits");ok(new RomValidator().isCompatible(u),"validation ROM");byte[] bad=u.clone();bad[0]^=1;ok(!new RomValidator().isCompatible(bad),"rejet ROM incorrecte");ok(Arrays.equals(new TrainerPatch().apply(f,Set.of()),f),"aucun cheat inchangé");
 testCheat(f,Cheat.TEMPS_INFINI,3,"Temps infini");testCheat(f,Cheat.INVINCIBILITE,1,"Invincibilité");testCheat(f,Cheat.SCHWING_ILLIMITE,1,"Schwing");testCheat(f,Cheat.TIR_RAPIDE,1,"Tir rapide / PCB");byte[] all=new TrainerPatch().apply(f,EnumSet.allOf(Cheat.class));ok(Arrays.equals(Arrays.copyOfRange(all,0x332,0x338),TrainerPatch.REPLACEMENT),"hook quatre cheats");ok((all[TrainerPatch.TRAINER]&255)==0x4e&&all[TrainerPatch.TRAINER+55]==0x75,"routine quatre cheats 56 octets");ok((((all[0x18e]&255)<<8)|(all[0x18f]&255))==TrainerPatch.checksum(all),"checksum Sega");byte[] occupied=f.clone();occupied[TrainerPatch.TRAINER]=0;boolean rejected=false;try{new TrainerPatch().apply(occupied,Set.of(Cheat.INVINCIBILITE));}catch(IOException e){rejected=true;}ok(rejected,"zone trainer FF");
 Path temp=Files.createTempDirectory("wwtest"),copy=temp.resolve("source.md");Files.write(copy,u);Path out=new RomCreationService().create(copy,temp,true,Set.of());ok(out.getFileName().toString().equals("Waynes_World_FR.bin"),"nom sortie");ok(Arrays.equals(Files.readAllBytes(copy),u),"source inchangée");ok(Arrays.equals(Files.readAllBytes(out),f),"service traduction");BufferedImage original=ImageIO.read(Path.of("Image.png").toFile()),banner=decode("/ui/wayne-banner.png.b64"),cover=decode("/ui/wayne-cover.png.b64");ok(banner.getWidth()==1506&&banner.getHeight()==246,"chargement bandeau");ok(cover.getWidth()==255&&cover.getHeight()==142,"chargement jaquette");ok(same(original,banner,15,55),"bandeau issu d'Image.png");ok(same(original,cover,1203,341),"jaquette issue d'Image.png");ok(Cheat.values().length==4,"exactement quatre cheats");System.out.println("TOTAL: "+tests+" tests");}
 static void testCheat(byte[] f,Cheat c,int writes,String n)throws Exception{byte[] r=new TrainerPatch().apply(f,Set.of(c));ok(Arrays.equals(Arrays.copyOfRange(r,0x332,0x338),TrainerPatch.REPLACEMENT)&&r[TrainerPatch.TRAINER+6]==0x13&&r[TrainerPatch.TRAINER+6+writes*8]==0x4e,n);}
 static BufferedImage decode(String n)throws Exception{return ImageIO.read(new ByteArrayInputStream(Base64.getMimeDecoder().decode(res(n))));}static boolean same(BufferedImage a,BufferedImage b,int x,int y){for(int j=0;j<b.getHeight();j++)for(int i=0;i<b.getWidth();i++)if(a.getRGB(x+i,y+j)!=b.getRGB(i,j))return false;return true;}}
